                      onClick={() => {
                        if (typeof navigator === 'undefined' || !navigator.geolocation) {
                          Swal.fire({ icon: 'error', title: 'অসমর্থিত ডিভাইস', text: 'আপনার ডিভাইসে লোকেশন সার্ভিস সাপোর্ট করছে না।' });
